import re

for line in ["Emma 45 coins", "Ben 7 coins", "wrong line"]:
    m = re.search(r"(\w+) (\d+) coins", line)
    if m:
        print(m.group(1), "->", int(m.group(2)))
    else:
        print("No match:", line)

project_task.solution:
import re

def parse(command):
    m = re.fullmatch(r"go (north|south|east|west) (\d+)", command)
    if m:
        return (m.group(1), int(m.group(2)))
    return None

print(parse("go north 3"))
print(parse("fly to the sky"))
